function nextView(){const hasReviewedDetails=reviewConfirmed(state);return head(4,hasReviewedDetails?'Your preparation package is ready.':'Your preparation package is started.',hasReviewedDetails?'Your reviewed details are organized for your application. Download your package to keep them and see what still needs attention.':'Add and review your details to build a package you can use with your application.',false)+`${!hasReviewedDetails?`<section class="card pad"><p data-i18n=ui146>Confirm your reviewed details before generating or downloading a package.</p>${btn('to-confirm','Go to Review',true)}</section>`:''}<p class="small">${esc(tr('Official PDF language: English. Changing the interface language does not change the form language.'))} ${uiLocale()==='es-US'?esc(tr('Spanish PDF templates are not available in this preview.')):''}</p><div class="program-cards">${programSelected(state,'CalFresh')?`<section class="card cf-program"><h2>CalFresh</h2>${applicationFormButtons('CalFresh',hasReviewedDetails)}<details class="application-review-details"><summary data-i18n=ui148>Review details again</summary>${startingSummary(state,'calfresh',esc)}<p>${state.facts.filter(usable).length} details confirmed. Unprepared answers remain open.</p>${applicationAnswerSummary(state,'cf285',esc)}${btn('guide','Continue my CalFresh application',false)}</details></section>`:''}${programSelected(state,'Medi-Cal')?'<section class="card cf-program"><h2>Medi-Cal</h2>'+applicationFormButtons('Medi-Cal',hasReviewedDetails)+'<details class="application-review-details"><summary data-i18n=ui148>Review details again</summary>'+startingSummary(state,'medical',esc)+'<p>Shared evidence remains available. Medi-Cal guided completion is not included in this build. Its submission status stays separate.</p><p>'+esc(submission(state,'Medi-Cal'))+'</p>'+applicationAnswerSummary(state,'ccfrm604',esc)+btn('documents','Review Medi-Cal evidence')+btn('followup','Medi-Cal follow-up',false,'data-track="Medi-Cal"')+'</details></section>':''}</div><p>${['CalFresh','Medi-Cal'].filter(p=>state.programs.has(p)&&!programStarted(state,p)).map(p=>btn('start-program','Optional: answer the '+p+' quick check',false,`data-start-program="${p==='CalFresh'?'calfresh':'medical'}"`)).join(' ')}</p><section class="card cf-summarybar"><p data-i18n=ui155>Your prepared files are supporting tools. The quick check is preliminary. Full eligibility has not been determined.</p>${btn('package','Download my package',true,hasReviewedDetails?'':'disabled')}</section>`;}
