async function demoDocuments(){
 if(state.household?.configured){toast('Clear this preparation before opening a fictional household demo.');return;}
 if(state.busy||state.docs.length)return;
 const token=++epoch;controller=new AbortController();state.busy=true;state.progress='Opening fictional demo documents';render();
 try{
  const files=[];
  for(const name of ['03-september-pay.pdf','01-bill-with-previous-balance.pdf','05-short-note.txt']){
   const response=await fetch(new URL('../demo/ai-components/'+name,import.meta.url),{signal:controller.signal});
   if(!response.ok)throw Error('Demo file is unavailable. Rebuild the extension.');
   files.push(new File([await response.arrayBuffer()],name,{type:name.endsWith('.pdf')?'application/pdf':'text/plain'}));
  }
  if(token!==epoch)return;
  state.busy=false;state.demo=true;const demoForms=demoApplicationAnswers();for(const [id,answers] of Object.entries(demoForms))if(!state.formAnswers[id]?.answers.length)state.formAnswers[id]=answers;
  await intake(files,{mode:'labels'});
  if(token+1===epoch)for(const d of state.docs)d.demoSource=true;
 }finally{if(token===epoch){state.busy=false;render();}}
}
