 if(a==='source-context')return sourceContextDialog(b.dataset.id);
 if(a==='save-source-context'){setSourceContext(state,b.dataset.id,Object.fromEntries(['person','home_address','home_city','home_state','home_zip','document_date','pay_date','period_start','period_end'].map(k=>[k,$('#source-'+k).value])));close();render();return;}
 if(a==='start-program'){state.activeStarting=b.dataset.startProgram;return navigate('quick');}
 if((['official-form','package','export'].includes(a)||a.startsWith('form-'))&&!reviewConfirmed(state)){navigate('confirm');toast('Confirm reviewed details before generating or downloading a package.');return;}
 if(a==='official-form'||a.startsWith('form-'))return officialForms.action(a,b);
